import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"坎下艮上 蒙：","description":"京氏易傳 - 坎下艮上 蒙：","frontmatter":{"title":"坎下艮上 蒙：","description":"京氏易傳 - 坎下艮上 蒙："},"headers":[],"relativePath":"classics/jingshi/054.md","filePath":"classics/jingshi/054.md"}'),r={name:"classics/jingshi/054.md"};function l(c,a,o,d,p,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎下艮上-蒙",tabindex:"-1"},[i("坎下艮上 蒙： "),e("a",{class:"header-anchor",href:"#坎下艮上-蒙","aria-label":"Permalink to “坎下艮上 蒙：”"},"​")],-1),e("p",null,"積陽居陰，止於坎陷。養純正素，居中得位。《易》雲：“山下出泉，蒙”。（虎易注：此句出象辭。）二象摽正，天下通也。擊暗釋疑，陽道行也；內實外正，暗得明，陰附於陽，稚道亨也。故曰：“蒙養正”。與艮為飛伏。【丙戌土，乙酉金。】（虎易注：乙酉金當為己酉金之誤。）諸位立世，（虎易注：諸位當是諸侯之誤。）元士為應。【六四，初六。】",-1),e("p",null,"建始壬子至丁巳，【大雪，小滿。】積算起丁巳至丙辰，週而復始。火土入艮坎。【火土二象入卦同算。】",-1),e("p",null,"五星從位起太陰，【水星北方，入宮起算。】胃宿從位降丙戌土，【二十八宿，分胃宿入蒙卦六四丙戌土上。】分氣候三十六。【起數二十八，從六位推算。】（虎易注：二十八當為三十六之誤。）",-1),e("p",null,"山下見水，畜聚居中，分流萬派，六位不居，吉凶適變，水土分也。【五行入卦算吉凶，逐四時行囚廢王，吉則王，兇則廢。】【虎易注：王通旺之義。】陰陽進退，歲時物也。六五陽中積陰，入巽見陰中陽，二氣相蕩，不可盈望。次降入風水渙卦。【六五變入九五，陽中陰入陽中陽，適變往於他宮，位不出本宮。】",-1)])])}const h=s(r,[["render",l]]);export{f as __pageData,h as default};
